package org.sleepwell.app;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class AutomationPolicyTest {
    private AutomationRule rule(AutomationRule.Transport transport,String destination,String topic,String user,String secret){return new AutomationRule("12345678-1234-1234-1234-123456789012","My rule",AutomationEvent.Kind.TRACKING_STARTED,transport,false,0,destination,topic,user,secret);}
    @Test public void eventsAreMinimalStableAndSeparateKinds(){AutomationEvent a=AutomationEvent.occurrence(AutomationEvent.Kind.TRACKING_STARTED,"personal record name",1000,false),b=AutomationEvent.occurrence(AutomationEvent.Kind.TRACKING_STARTED,"personal record name",2000,false),c=AutomationEvent.occurrence(AutomationEvent.Kind.TRACKING_STOPPED,"personal record name",2000,false);assertEquals(a.id,b.id);assertNotEquals(a.id,c.id);assertFalse(a.json().contains("personal"));assertTrue(a.json().contains("\"schema\":1"));assertTrue(a.json().contains("\"test\":false"));}
    @Test public void defaultOffRulesValidateAllDestinations(){for(AutomationRule r:List.of(rule(AutomationRule.Transport.INTENT,"net.dinglisch.android.taskerm","","",""),rule(AutomationRule.Transport.WEBHOOK,"https://example.org/hook?key=secret","","","token"),rule(AutomationRule.Transport.MQTT,"ssl://example.org:8883","room/sleep","user","password"))){r.validate();assertFalse(r.enabled);}}
    @Test public void rejectsCleartextEmbeddedCredentialsAndWildcards(){for(AutomationRule r:List.of(rule(AutomationRule.Transport.WEBHOOK,"http://example.org","","",""),rule(AutomationRule.Transport.WEBHOOK,"https://a:b@example.org","","",""),rule(AutomationRule.Transport.WEBHOOK,"https://example.org/#fragment","","",""),rule(AutomationRule.Transport.MQTT,"tcp://example.org","room","",""),rule(AutomationRule.Transport.MQTT,"ssl://example.org","room/#","",""),rule(AutomationRule.Transport.MQTT,"ssl://example.org","room","","password"),rule(AutomationRule.Transport.INTENT,"any package","","",""))){try{r.validate();fail(r.destination);}catch(IllegalArgumentException expected){}}}
    @Test public void rejectsHeaderInjection(){try{rule(AutomationRule.Transport.WEBHOOK,"https://example.org","","","value\r\nOther: injected").validate();fail();}catch(IllegalArgumentException expected){}}
    @Test public void retryBudgetAndExpiryAreBounded(){assertTrue(AutomationDelivery.retry(true,1,1000,2000));assertFalse(AutomationDelivery.retry(false,1,1000,2000));assertFalse(AutomationDelivery.retry(true,6,1000,2000));assertFalse(AutomationDelivery.retry(true,1,1000,1000+AutomationDelivery.MAX_AGE));assertFalse(AutomationDelivery.retry(true,1,2000,1000));assertEquals(60000,AutomationDelivery.retryDelay(1));assertEquals(10800000,AutomationDelivery.retryDelay(5));}
    @Test public void trackingEmitsOnePairForLifetimeAndIgnoresCancelledAdmission(){List<String> events=new ArrayList<>();AutomationTracking tracking=new AutomationTracking((kind,id)->events.add(kind+":"+id));tracking.stopped();tracking.started(0,1000);tracking.started(1,1000);tracking.started(1,1000);tracking.stopped();tracking.stopped();assertEquals(List.of("TRACKING_STARTED:1:1000","TRACKING_STOPPED:1:1000"),events);}
}
